def rename_content_types(apps, schema_editor):
    """Move mainline content types onto the split app without losing permissions."""
    ContentType = apps.get_model("contenttypes", "ContentType")
    Permission = apps.get_model("auth", "Permission")
    for model_name in ['metric', 'metriccategory', 'direct', 'derived', 'evaluation', 'observation', 'measurement', 'evaluationplugin', 'evaluationinput', 'artifact']:
        old = ContentType.objects.filter(
            app_label="aisc_backend", model=model_name
        ).first()
        if old is None:
            continue
        new = ContentType.objects.filter(
            app_label='aisc_evaluation', model=model_name
        ).first()
        if new is None:
            old.app_label = 'aisc_evaluation'
            old.save(update_fields=["app_label"])
            continue
        # A row already exists under the new label: move permissions that do
        # not clash, then drop the stale row.
        existing = set(
            Permission.objects.filter(content_type=new).values_list(
                "codename", flat=True
            )
        )
        for permission in Permission.objects.filter(content_type=old):
            if permission.codename in existing:
                permission.delete()
            else:
                permission.content_type = new
                permission.save(update_fields=["content_type"])
        old.delete()


